const body=document.body,main=document.querySelector('#main-site'),pause=document.querySelector('#pause-opening');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const key='recont-opening-v10';let seen=false;try{seen=localStorage.getItem(key)==='seen'}catch{}
export const opening={elapsed:0,done:false,paused:false,progress:0,needsRender:true};
export function finishOpening(focus=true){opening.done=true;opening.progress=.23;opening.elapsed=9.3;opening.needsRender=true;body.style.setProperty('--hero-reveal','1');body.classList.remove('opening');main.inert=false;main.style.removeProperty('--aperture');document.querySelector('#journey').inert=true;try{localStorage.setItem(key,'seen')}catch{}if(focus)document.querySelector('#main-title').focus({preventScroll:true});}
function startOpening(){opening.elapsed=0;opening.progress=0;opening.needsRender=true;opening.done=false;opening.paused=false;pause.textContent='一時停止 Ⅱ';pause.setAttribute('aria-pressed','false');main.inert=true;body.classList.add('opening');body.style.setProperty('--hero-reveal','0');body.style.setProperty('--old-header','1');window.scrollTo(0,0);}
document.querySelector('#skip-opening').onclick=()=>finishOpening();document.querySelector('#replay-opening').onclick=()=>{startOpening();document.querySelector('#skip-opening').focus()};pause.onclick=()=>{opening.paused=!opening.paused;pause.textContent=opening.paused?'再生 ▷':'一時停止 Ⅱ';pause.setAttribute('aria-pressed',String(opening.paused))};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!opening.done)finishOpening()});reduced.addEventListener('change',e=>{if(e.matches)finishOpening()});
export function advanceOpening(dt){if(opening.done||opening.paused||document.hidden)return;opening.elapsed+=dt;const t=opening.elapsed;opening.progress=t<6?.04*(t/6):t<9?.04+(t-6)/3*.06:t<15?.1+(t-9)/6*.1:t<18?.20+(t-15)/3*.03:.23;const reveal=Math.max(0,Math.min(1,(t-7.8)/1.5));body.style.setProperty('--hero-reveal',String(reveal));body.style.setProperty('--old-header',String(1-Math.max(0,Math.min(1,t-7.4))));document.querySelector('#opening-progress').style.transform='scaleX('+Math.min(1,t/9.3)+')';if(t>=9.3)finishOpening();}
if(seen||reduced.matches||location.hash){finishOpening(false)}else startOpening();
